<script setup>
import { computed,ref } from 'vue'
import { onShow,onHide,onUnload } from '@dcloudio/uni-app'
import AppNavBar from './AppNavBar.vue'
import MemberFields from './MemberFields.vue'
import { loadCloudProfile,saveCloudProfile,readCloudReportStatus } from '../services/cloud-profile.js'
import { request } from '../services/request.js'
import { sessionRevision } from '../services/session.js'
import { ageLabel } from '../utils/member-age.js'
import { diseaseSummary } from '../utils/health.js'
import { localDate } from '../utils/meal-state.js'
import { mealDate } from '../services/diet-journal-client.js'
const props=defineProps({id:String})
const profile=ref(null),draft=ref(null),editing=ref(false),busy=ref(false),error=ref(''),records=ref([]),dietError=ref(''),reportError=ref('')
const member=computed(()=>profile.value?.members.find(m=>String(m.id)===props.id))
const labels={breakfast:'早餐',lunch:'午餐',dinner:'晚餐',snack:'加餐'}
let epoch=0
function hide(){epoch++;profile.value=null;records.value=[];busy.value=false;error.value='';dietError.value='';reportError.value='';draft.value=null;editing.value=false}
async function load(){if(busy.value)return;const mine=++epoch,rev=sessionRevision();busy.value=true;error.value='';try{const p=await loadCloudProfile();if(mine!==epoch||rev!==sessionRevision())return;profile.value=p;if(!member.value)throw new Error('这位成员已不在当前家庭，请返回重新选择');if(member.value.healthMemberId){try{const status=await readCloudReportStatus(member.value.healthMemberId);if(mine!==epoch||rev!==sessionRevision())return;member.value.reportStatus=status}catch(e){if(mine===epoch)reportError.value=e.message}try{const {data}=await request({path:'/api/health/v1/members/'+member.value.healthMemberId+'/diet-logs'});if(mine!==epoch||rev!==sessionRevision())return;records.value=data.filter(r=>mealDate(r.snapshot?.meal?.eaten_at)===localDate())}catch(e){if(mine===epoch)dietError.value=e.message}}else dietError.value='这位成员尚未关联饮食记录来源。'}catch(e){if(mine===epoch)error.value=e.message}finally{if(mine===epoch)busy.value=false}}
function edit(){draft.value=JSON.parse(JSON.stringify(member.value));editing.value=true}
async function save(){if(busy.value||!draft.value?.name?.trim())return;const mine=epoch,rev=sessionRevision();busy.value=true;error.value='';try{const next=JSON.parse(JSON.stringify(profile.value));next.members=next.members.map(m=>m.id===draft.value.id?draft.value:m);const saved=await saveCloudProfile(next);if(mine===epoch&&rev===sessionRevision()){profile.value=saved;editing.value=false;draft.value=null}}catch(e){if(mine===epoch)error.value=e.message}finally{if(mine===epoch)busy.value=false}}
function record(r){uni.navigateTo({url:'/pages/records/detail?id='+encodeURIComponent(r.id)+'&memberId='+encodeURIComponent(member.value.healthMemberId)})}
onShow(load);onHide(hide);onUnload(hide)
</script>
<template><view class="screen member-detail"><AppNavBar><view class="nav-row"><button class="icon-button" @click="editing?editing=false:uni.navigateBack()">‹</button><text class="nav-title">{{member?.name||'成员'}}的健康档案</text><button v-if="member" class="edit" :disabled="busy" @click="editing?save():edit()">{{editing?'保存':'编辑'}}</button></view></AppNavBar><text v-if="busy" class="safe-note">正在核对档案…</text><view v-if="error" class="card main-card"><text class="inline-error">{{error}}</text><button :disabled="busy" @click="load">重新读取</button></view><template v-if="member"><view class="card identity"><view class="avatar">{{member.name.slice(0,1)}}</view><view><text>{{member.name}}</text><text>{{ageLabel(member)}} · {{member.gender}} · {{member.relation}}</text></view></view><template v-if="editing"><MemberFields :member="draft"/><button class="primary-button" :disabled="busy" @click="save">保存档案</button><button class="secondary-button" :disabled="busy" @click="editing=false">取消修改</button></template><template v-else><view class="card main-card"><text class="section-title">基础资料</text><text>身高 {{member.height||'未填写'}} cm · 体重 {{member.weight||'未填写'}} kg</text><text>出生日期 {{member.birthDate||'未填写'}} · 关系 {{member.relation}}</text><text class="subheading">偏好与目标</text><text>饮食目标：{{member.goals.join('、')||'未填写'}}</text><text>口味：{{member.tastePreferences.join('、')||'未填写'}}</text><text>菜系：{{member.cuisines.join('、')||'未填写'}}</text><text class="subheading">饮食限制、医生要求与报告</text><MemberFields :member="member" :read-only="true" :sections="['restrictions','reports']"/><text v-if="reportError" class="inline-error">报告状态暂未读取：{{reportError}}</text></view><view class="card main-card"><text class="section-title">基础病情况</text><text>{{member.healthStatus==='set'?member.conditions.join('、'):member.healthStatus==='none'?'没有已知基础病':'暂不填写'}}</text><text>用户自述 · {{diseaseSummary(member)}}</text></view><view class="card main-card"><text class="section-title">每日饮食</text><text>今日实际保存的饮食记录，不是计划菜单。</text><text v-if="dietError" class="inline-error">{{dietError}}</text><button v-for="r in records" :key="r.id" class="record" @click="record(r)"><text>{{labels[r.snapshot.meal.meal_type]}}</text><text>{{r.snapshot.meal.items.filter(i=>!i.excluded).map(i=>i.name).join('、')}} ›</text></button><text v-if="!records.length&&!dietError">今天尚未保存饮食记录，不代表没有用餐。</text></view><button class="secondary-button" @click="uni.navigateTo({url:'/pages/family-shared/index?memberId='+encodeURIComponent(member.id)})">实测指标与修改历史</button></template></template></view></template>
<style scoped>.identity{display:flex;align-items:center;gap:20rpx;padding:28rpx;margin:32rpx 0}.avatar{width:92rpx;height:92rpx;display:flex;align-items:center;justify-content:center;background:#eaf2ed;border-radius:28rpx;font-size:34rpx;font-weight:800}.identity>view:last-child,.main-card{display:flex;flex-direction:column;gap:16rpx}.main-card{padding:28rpx;margin:22rpx 0;font-size:26rpx;line-height:1.7}.identity text{display:block;font-size:26rpx}.identity text:first-child{font-size:32rpx;font-weight:700}.edit,.subheading{color:#246b50;font-size:26rpx}.record{width:100%;text-align:left;border-top:1px solid #e0e5db;padding:16rpx 0;font-size:26rpx}.record text{display:block}</style>
